
"use client";

import { useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowRight,
  Eye,
  EyeOff,
  LockKeyhole,
  Mail,
  MessageCircle,
  Sparkles,
} from "lucide-react";

export default function HomePage() {
  const router = useRouter();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleSignIn(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setLoading(true);

    try {
      // TODO: Replace with your authentication API.
      // Redirect only after successful authentication.
      // router.push("/c/me");

      setError("Authentication is not configured yet.");
    } catch {
      setError("Unable to sign in. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="relative isolate flex min-h-dvh w-full items-center justify-center overflow-hidden bg-[#F4F9FE] px-4 py-10 sm:px-6">
      {/* Background */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10"
        style={{
          background:
            "radial-gradient(ellipse at 50% 45%, #FFFFFF 0%, #F4F9FE 65%, #E5F3FD 100%)",
        }}
      />

      {/* Top-right decorative curves */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -right-32 -top-48 h-[340px] w-[340px] rotate-[-20deg] rounded-full bg-[#B8E3FC] sm:-right-40 sm:-top-64 sm:h-[540px] sm:w-[540px]"
      />
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -right-48 -top-52 h-[290px] w-[290px] rotate-[-20deg] rounded-full bg-[#008EED] sm:-right-64 sm:-top-72 sm:h-[470px] sm:w-[470px]"
      />

      {/* Bottom-left decorative curves */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -bottom-52 -left-40 h-[340px] w-[340px] rounded-full bg-[#D7EEFC] sm:-bottom-[420px] sm:-left-[320px] sm:h-[850px] sm:w-[850px]"
      />
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -bottom-52 -left-48 h-[300px] w-[300px] rounded-full bg-gradient-to-tr from-[#02394F] via-[#087CAC] to-[#05A7F7] sm:-bottom-[470px] sm:-left-[390px] sm:h-[760px] sm:w-[760px]"
      />
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -bottom-52 -left-48 h-[230px] w-[230px] rounded-full bg-[#FD7E27] sm:-bottom-[460px] sm:-left-[390px] sm:h-[550px] sm:w-[550px]"
      />

      {/* Login card */}
      <section className="relative z-10 w-full max-w-[470px] overflow-hidden rounded-[26px] border border-white/90 bg-white px-6 pb-9 pt-12 shadow-[0_20px_70px_rgba(2,57,79,0.11)] sm:rounded-[30px] sm:px-12 sm:pb-12 sm:pt-14">
        {/* Top accent */}
        <div className="absolute left-1/2 top-0 h-[6px] w-36 -translate-x-1/2 rounded-b-full bg-[#008EED]" />

        {/* Branding */}
        <div className="flex flex-col items-center">
          <div className="relative flex h-[82px] w-[82px] items-center justify-center rounded-[22px] bg-[#E5F3FD]">
            <MessageCircle
              size={46}
              strokeWidth={2}
              className="text-[#008EED]"
            />
            <Sparkles
              size={22}
              strokeWidth={2.5}
              className="absolute right-3 top-3 fill-[#008EED] text-[#008EED]"
            />
          </div>

          <h1 className="mt-6 text-center text-[30px] font-bold tracking-tight text-[#02394F] sm:text-[34px]">
            Messenger AI
          </h1>
        </div>

        {/* Login form */}
        <form onSubmit={handleSignIn} className="mt-9 space-y-4">
          <div className="relative">
            <Mail
              size={20}
              className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[#8195AA]"
            />
            <input
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              placeholder="Email"
              aria-label="Email"
              autoComplete="email"
              required
              className="h-14 w-full rounded-2xl border border-[#DCE6EF] bg-white pl-12 pr-4 text-[15px] text-[#02394F] outline-none transition placeholder:text-[#91A2B4] focus:border-[#008EED] focus:ring-2 focus:ring-[#008EED]/10"
            />
          </div>

          <div className="relative">
            <LockKeyhole
              size={20}
              className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[#8195AA]"
            />
            <input
              type={showPassword ? "text" : "password"}
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              placeholder="Password"
              aria-label="Password"
              autoComplete="current-password"
              required
              className="h-14 w-full rounded-2xl border border-[#DCE6EF] bg-white pl-12 pr-12 text-[15px] text-[#02394F] outline-none transition placeholder:text-[#91A2B4] focus:border-[#008EED] focus:ring-2 focus:ring-[#008EED]/10"
            />
            <button
              type="button"
              onClick={() => setShowPassword((value) => !value)}
              aria-label={showPassword ? "Hide password" : "Show password"}
              aria-pressed={showPassword}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-[#8195AA] transition hover:text-[#008EED]"
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>

          {error && (
            <p role="alert" className="text-sm text-red-600">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="relative flex h-14 w-full items-center justify-center rounded-2xl bg-[#008EED] px-5 text-base font-semibold text-white transition hover:bg-[#057FD1] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#008EED] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {loading ? "Signing in..." : "Sign in"}
            {!loading && (
              <ArrowRight size={21} className="absolute right-5" />
            )}
          </button>
        </form>
      </section>
    </main>
  );
}
